from pathlib import Path
import hashlib
import json

root = Path('products/services/welfare-tender')
terms = Path('products/services/payment-handoff/terms-welfare-followon-v1.md')
out = root / 'followon-rehearsal' / 'source-backed-case.md'
if out.exists():
    print(out.read_text())
    raise SystemExit(0)

candidates = []
for path in sorted(root.rglob('*.json')):
    if 'followon-rehearsal' in path.parts:
        continue
    try:
        raw = path.read_bytes()
        package = json.loads(raw)
    except (OSError, ValueError):
        continue
    if not isinstance(package, dict):
        continue
    releases = package.get('releases', [])
    for release in releases if isinstance(releases, list) else []:
        if not isinstance(release, dict):
            continue
        if '104449-2026' in str(release.get('id', '')) and isinstance(release.get('tender'), dict):
            candidates.append((path, raw, release))

terms_bytes = terms.read_bytes()
lines = ['# Welfare tender follow-on rehearsal', '', 'Fictional request: A welfare provider asks what to verify before deciding whether to pursue notice 104449-2026. No provider facts are assumed. Produced by autonomous AI agents for offline acceptance review.', '', f'Terms: `{terms}` (SHA-256 `{hashlib.sha256(terms_bytes).hexdigest()}`).', '']
if candidates:
    path, raw, release = candidates[0]
    tender = release['tender']
    lines.extend([f'Saved OCDS release `{release["id"]}` from `{path}` (SHA-256 `{hashlib.sha256(raw).hexdigest()}`). Source currency is unverified.', '', '| Decision input | Saved OCDS value |', '| --- | --- |'])
    for field in ('title', 'status', 'procurementMethodDetails', 'tenderPeriod', 'enquiryPeriod', 'value', 'submissionMethod', 'submissionMethodDetails', 'eligibilityCriteria', 'awardCriteria'):
        value = json.dumps(tender[field], ensure_ascii=False) if field in tender else 'Unavailable in saved release'
        lines.append(f'| {field} | {value.replace(chr(124), chr(92) + chr(124))} |')
    lines.extend(['', 'Before committing bid effort, verify the live deadline, submission route, current tender pack and applicable requirements. Compare those requirements with the provider’s documented qualifications and capacity. Eligibility and submission readiness remain unverified.'])
else:
    lines.extend(['Source check unresolved: no parseable OCDS release with 104449-2026 in its release ID was found in the selected JSON files. Confirm the official artifact and notice identifier before filling the decision inputs.'])
lines.extend(['', 'Acceptance is pending comparison with the exact terms. This rehearsal establishes no private execution, recipient delivery, administrative acceptance or settlement.'])
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text('\n'.join(lines) + '\n', encoding='utf-8')
print(out.read_text())
